#ifndef TOOLS_CLANG_SPANIFY_TESTS_ANGLE_AUTOGEN_AUTOGEN_HELPER_H_
#define TOOLS_CLANG_SPANIFY_TESTS_ANGLE_AUTOGEN_AUTOGEN_HELPER_H_

// Simulates an autogenerated ANGLE header (e.g.
// src/libANGLE/Context_gles_ext_autogen.h). Files whose path contains
// "autogen" are excluded because rewriting them is pointless: the generator
// would overwrite the change on its next run.

// Declared here but defined out-of-line in a regular source file. The
// exclusion must follow the redeclaration chain, otherwise the definition's
// signature is rewritten while this declaration is left intact.
void AutogenFunction(const int* buffer);

inline void AutogenInlineFunction(const int* buffer) {
  int x = buffer[0];
}

#endif  // TOOLS_CLANG_SPANIFY_TESTS_ANGLE_AUTOGEN_AUTOGEN_HELPER_H_
